```python
from collections import Counter

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Examples:
    >>> histogram('a b c')
    {'a': 1, 'b': 1, 'c': 1}
    >>> histogram('a b b a')
    {'a': 2, 'b': 2}
    >>> histogram('a b c a b')
    {'a': 2, 'b': 2}
    >>> histogram('b b b b a')
    {'b': 4}
    >>> histogram('')
    {}
    """
    # Empty or whitespace‑only input yields an empty dictionary
    if not test.strip():
        return {}

    # Split the input string into individual tokens (letters/words)
    words = test.split()

    # Count how many times each token appears
    counts = Counter(words)

    # Determine the highest frequency among the counted letters
    max_frequency = max(counts.values())

    # Return a dictionary containing only those letters whose count equals the max frequency
    return {letter: freq for letter, freq in counts.items() if freq == max_frequency}
```

